 pathParams: ['tableName', 'sys_id'],
 successActionType: 'FETCH_SUCCESS',
 errorActionType: 'FETCH_FAILED'
 }),
 'FETCH_SUCCESS': (coeffects) => {
 const { action, updateState } = coeffects;
 const { result } = action.payload;
 const { number, short_description } = result;
 updateState({ number, short_description });
 },
 'FETCH_FAILED': (coeffects) => {

 },
 'FETCH_ATTACHMENTS': createHttpEffect('api/now/attachment', {
 method: 'GET',
 queryParams: ['sysparm_query', 'sysparm_limit'],
 successActionType: 'FETCH_ATTACHMENT_SUCCESSFUL',
 errorActionType: 'FETCH_ATTACHMENT_FAILURE'
 }),
 'FETCH_ATTACHMENT_SUCCESSFUL': (coeffects) => {
 const { action, updateState } = coeffects;
 const { result } = action.payload;
 updateState({ attachments: result || [], filteredAttachments: result || [] });
 },
 'FETCH_ATTACHMENT_FAILURE': (coeffects) => {
 // const { action, updateState } = coeffects;
 },
 'DOWNLOAD_SELECTED': ({ state }) => {

 const selected = state.selectedIds;

 if (!selected.length) return;

 selected.forEach(sysId => {

 const url = `/sys_attachment.do?sys_id=${sysId}`;

 // triggers browser download
 window.open(url, '_blank');
 });
 },
 TRANSFER_ATTACHMENTS:()=>{
 console.log('TRANSFER_ATTACHMENTS');
 },
 'SEND_CUSTOM_ACTION': ({ state, dispatch }) => {
 dispatch('CUSTOM_ACTION', {
