 });
 },
 'SELECTED_FILE_NAME': ({ state, dispatch }) => {
 dispatch('SELECTED_FILE', {
 selectedIds: state.selectedIds
 });
 }, 'TOGGLE_ATTACHMENT': ({ action, state, updateState }) => {
 const { sysId, checked } = action.payload;

