	};
	const toggleMenuOpen = (menuOpen) => {
		updateState({ isMenuOpen: !menuOpen });
	};
	const updateSearchTerm = (e) => {
		updateState({ searchTerm: e.target.value });
	};
	const allAttachmentAction = () => {

		if (allSelected) {
			updateState({ selectedIds: [] });
